    # correct_maxes = torch.max(x, dim, keepdim=True)[0]
    # assert(correct_maxes == maxes)
    maxes = torch.full((1, x.shape[1], x.shape[2], 1), max_constants[layer_id]) # Same shape as x, filled with constant_value
